      if (act === "exam" && X.Campus) { X.Campus.exam(); return; }
      if (act === "schedule" && X.Campus) { X.Campus.schedule(); return; }
      if (act === "mic") { X.openKaraoke(); return; }
      if (act === "ach") { X.openAch(); return; }
      if (act === "love") { X.openLove(); return; }
