  var AUTO_KEY = "xz581_autosave";

  /* ============================================================
     1. 自动存档
     ============================================================ */
  function snapshot() {
    try {
      if (window.SAVE_SYS && SAVE_SYS.snapshot) {
        var raw = SAVE_SYS.snapshot();
        if (raw) { try { localStorage.setItem(AUTO_KEY, raw); } catch (e) {} return true; }
      }
      if (typeof saveGame === "function" && typeof G !== "undefined" && G) {
        saveGame();
        var raw2 = localStorage.getItem("xz_save_v1");
        if (raw2) { try { localStorage.setItem(AUTO_KEY, raw2); } catch (e) {} return true; }
      }
    } catch (e) {}
    return false;
  }
  function hasAuto() {
    try { return !!localStorage.getItem(AUTO_KEY); } catch (e) { return false; }
  }
  function continueAuto() {
    try {
      var raw = localStorage.getItem(AUTO_KEY);
      if (!raw) { X.toast("没有可继续的存档"); return; }
      /* 优先用存档系统；它在部分构建里不是全局，做兜底：直接写入快速槽再读档 */
      if (window.SAVE_SYS && typeof SAVE_SYS.loadRaw === "function") {
        if (SAVE_SYS.loadRaw(raw)) return;
      }
      var parsed = JSON.parse(raw);
      if (!parsed || typeof parsed.name === "undefined") { X.toast("存档已损坏"); return; }
      localStorage.setItem("xz_save_v1", raw);
      if (typeof window.continueGame === "function") {
        try { if (window.X570 && X570.closeMode) X570.closeMode(); } catch (e) {}
        window.continueGame();
        X.toast("📖 已继续上次游戏");
        return;
      }
      X.toast("读档函数不可用");
    } catch (e) { X.toast("读档失败：" + (e.message || e)); }
  }
  X.autoSave = snapshot;
  X.continueGame = continueAuto;
  /* 每 45 秒自动存档 */
  setInterval(function () {
    try {
      var g = X.G();
      if (g && !g.over) snapshot();
    } catch (e) {}
  }, 45000);
  /* 每天结束额外存档 */
  function wrapDayEnd() {
    if (typeof window.dayEnd !== "function" || window.__x581DayEnd) return;
    window.__x581DayEnd = true;
    var orig = window.dayEnd;
    window.dayEnd = function () {
      try { snapshot(); } catch (e) {}
      return orig.apply(this, arguments);
    };
  }

  /* ============================================================
     2. 顶部歌词条（前/中/后三行，当前句高亮，播完左滑）
     ============================================================ */
  function ensureLyricBar() {
    var bar = document.getElementById("x581LyricBar");
    if (bar) return bar;
    bar = document.createElement("div");
    bar.id = "x581LyricBar";
    bar.innerHTML = '<div class="lb-prev"></div><div class="lb-cur"></div><div class="lb-next"></div>';
    document.body.appendChild(bar);
    return bar;
  }
  var lastLrcIdx = -2;
  function tickLyric() {
    var mode = document.getElementById("x570Mode");
    var bar = document.getElementById("x581LyricBar");
    if (!bar) return;
    var onMode = mode && mode.classList.contains("show");
    if (!onMode) { bar.style.display = "none"; document.body.classList.remove("x581-has-lyric"); return; }
    var cur = "", prev = "", next = "", idx = -1;
    try {
      if (typeof xzCurLrc === "function") {
        var info = xzCurLrc();
        if (info && info.idx >= 0) {
          idx = info.idx;
          cur = info.lrc[idx][1];
          prev = info.lrc[idx - 1] ? info.lrc[idx - 1][1] : "";
          next = info.lrc[idx + 1] ? info.lrc[idx + 1][1] : "";
        }
      }
    } catch (e) {}
    if (!cur) {
      /* 音乐没在放时，用固定氛围句 */
      var amb = ["心 之 所 向 · 杭州西子实验学校", "记得选择最适合你的模式", "剧情模式推荐第一次体验", "戴上耳机，校园 BGM 更有感觉"];
      cur = amb[Math.floor(Date.now() / 4000) % amb.length];
    }
    bar.style.display = "flex";
    if (idx !== lastLrcIdx) {
      var c = bar.querySelector(".lb-cur");
      bar.classList.add("lb-slide");
      setTimeout(function () {
        bar.querySelector(".lb-prev").textContent = prev ? "🎵 " + prev : "";
        bar.querySelector(".lb-cur").textContent = cur;
        bar.querySelector(".lb-next").textContent = next ? "🎵 " + next : "";
        bar.classList.remove("lb-slide");
      }, 160);
      lastLrcIdx = idx;
    }
  }

