      '</svg>' +
      '<div id="x581BuildBar" style="width:min(70vw,320px);height:10px;background:rgba(0,0,0,.12);border-radius:999px;overflow:hidden;margin-top:18px"><i style="display:block;height:100%;width:0;background:linear-gradient(90deg,#3ddc97,#6c8cff);transition:width .3s"></i></div>' +
      '<div id="x581BuildPct" style="margin-top:8px;color:#355;font-size:13px;font-weight:700">0%</div>';
    document.body.appendChild(ov);
