    sec.className = "x581-pf-sec x581-pf-buffs";
    sec.innerHTML = "<h4>🎯 当前状态 Buff</h4>" + buffs.map(function (b) {
      return '<span class="x581-chip ' + (b.good ? "x581-buff-good" : "x581-buff-bad") + '">' + b.ic + " " + X.esc(b.n) + " <span style='opacity:.7'>· " + X.esc(b.d) + "</span></span>";
    }).join("");
