/* ===== X580/581 fragment: patch583_calligraphy.js ===== */
/* [X590-OPT] 旧版 X583 书法交替已被 X590 主视觉系统完全取代；
   为避免两套书法 + MutationObserver 互相争夺「开始游戏」按钮的显隐类（导致按钮被遮盖/消失），
   在此强制跳过 X583 书法 IIFE（资源片段 patch583_assets 仍保留，仅停用其 DOM/定时器逻辑）。 */
window.__X583_CALLI__ = true;

/* patch583_calligraphy.js
   书法标题/开始游戏/版本号/制作者/诗句 交替显示 + 主题亮暗识别
   依赖 patch583_assets.js（window.X583A）与 X581.timer（可回退 window）。 */
(function () {
  if (window.__X583_CALLI__) return; window.__X583_CALLI__ = true;
  var T = (window.X581 && X581.timer) ? X581.timer : { setInterval: function (f, t) { return setInterval(f, t); }, setTimeout: function (f, t) { return setTimeout(f, t); } };
  function img(key, cls) {
    var src = window.X583A && X583A[key];
    if (!src) return null;
    var i = document.createElement('img');
    i.src = src;
    i.setAttribute('alt', '');
    i.setAttribute('draggable', 'false');
    i.className = cls || '';
    return i;
  }
  /* 解析颜色 rgb/rgba/#hex → 亮度（0~255） */
  function lum(c) {
    if (!c) return 30;
    c = c.trim();
    var r, g, b;
    if (c[0] === '#') {
      var h = c.slice(1);
      if (h.length === 3) h = h[0] + h[0] + h[1] + h[1] + h[2] + h[2];
      r = parseInt(h.slice(0, 2), 16); g = parseInt(h.slice(2, 4), 16); b = parseInt(h.slice(4, 6), 16);
    } else {
      var m = c.match(/(\d+(?:\.\d+)?)/g);
      if (!m) return 30;
      r = +m[0]; g = +m[1]; b = +m[2];
    }
    if (isNaN(r)) return 30;
    return 0.2126 * r + 0.7152 * g + 0.0722 * b;
  }
  function detectTheme() {
    var cs = getComputedStyle(document.body);
    var bg = cs.getPropertyValue('--bg-b') || cs.getPropertyValue('--bg-a') || '';
    var ink = cs.getPropertyValue('--ink') || cs.getPropertyValue('--txt') || '';
    var bgl = lum(bg);
    var dark = bgl < 120;
    document.body.classList.toggle('x583-dark', dark);
    document.body.classList.toggle('x583-light', !dark);
    return dark;
  }
  function start() {
    detectTheme();
    /* 切换皮肤时重新判断 */
    var mo = new MutationObserver(function () { detectTheme(); });
    mo.observe(document.body, { attributes: true, attributeFilter: ['class', 'data-theme'] });

    /* ---------- 标题 / 版本号交替（互斥的单一节奏，避免两个书法图同屏重叠）---------- */
    var t1 = document.querySelector('.hero-t1');
    var wrap = null;
    function getCarousel() { return document.querySelector('.x56-title-carousel'); }
    if (t1 && X583A && X583A.title) {
      wrap = document.createElement('span');
      wrap.className = 'x583-call x583-titlecall';
      wrap.appendChild(img('title'));
      var row = t1.parentNode;
      row.style.position = 'relative';
      row.appendChild(wrap);
    }
    var hv = document.getElementById('heroVersion');
    var vc = null;
    if (hv && X583A && X583A.ver) {
      vc = document.createElement('span');
      vc.className = 'x583-call x583-vercall';
      vc.appendChild(img('ver'));
      hv.parentNode.insertBefore(vc, hv.nextSibling);
    }
    /* phase: 0=全原版, 1=书法标题, 2=全原版, 3=书法版本（任意时刻只显示一个书法图） */
    var phase = 0;
    function applyPhase(p) {
      var titleOn = (p === 1);
      var verOn = (p === 3);
      if (wrap) wrap.classList.toggle('show', titleOn);
      if (t1) t1.classList.toggle('x583-hide', titleOn);
      /* 每次都重新查（hero/轮播可能晚于脚本创建），并隐藏整个标题轮播的所有 slide */
      var car = getCarousel();
      if (car) {
        car.style.transition = 'opacity .6s ease';
        car.style.opacity = titleOn ? '0' : '';
        car.style.visibility = titleOn ? 'hidden' : 'visible';
      }
      document.querySelectorAll('.x56-slide.x56-s-text, .x56-slide.x56-s-logo, .hero-title, .xz-load-title').forEach(function (el) {
        el.style.transition = 'opacity .6s ease';
        el.style.opacity = titleOn ? '0' : '';
        el.style.visibility = titleOn ? 'hidden' : 'visible';
      });
      if (vc) vc.classList.toggle('show', verOn);
      if (hv) hv.classList.toggle('x583-hide', verOn);
    }
    function masterTick() {
      phase = (phase + 1) % 4;
      applyPhase(phase);
    }
    applyPhase(0);
    T.setInterval(masterTick, 3600);
    T.setTimeout(masterTick, 2200);

    /* ---------- 开始游戏按钮文字与书法图交替 ---------- */
    var sb = document.getElementById('heroStartBtn');
    if (sb && X583A && X583A.start) {
      var label = sb.textContent;
      sb.innerHTML = '<span class="x583-btnlabel">' + label + '</span>';
      var sc = document.createElement('span');
      sc.className = 'x583-call x583-startcall';
      sc.appendChild(img('start'));
      sb.appendChild(sc);
      var sshow = false;
      function stick() {
        sshow = !sshow;
        sc.classList.toggle('show', sshow);
        sb.classList.toggle('x583-label-hide', sshow);
      }
      T.setInterval(stick, 3600);
      T.setTimeout(stick, 2400);
    }

    /* ---------- 制作者：进入首页后淡入一次 ---------- */
    if (X583A && X583A.maker) {
      var mk = document.createElement('div');
      mk.className = 'x583-call x583-maker';
      mk.appendChild(img('maker'));
      var sub = document.createElement('span');
      sub.className = 'x583-maker-sub';
      mk.appendChild(sub);
      document.body.appendChild(mk);
      function showMaker() {
        var hero = document.getElementById('heroPanel');
        if (!hero || getComputedStyle(hero).display === 'none') return;
        mk.classList.add('show');
        T.setTimeout(function () { mk.classList.remove('show'); }, 3600);
      }
      T.setTimeout(showMaker, 2600);
      T.setInterval(function () { if (!mk.classList.contains('show')) { T.setTimeout(showMaker, 800); } }, 22000);
    }

    /* ---------- 诗句：点开始游戏时全屏浮现 ---------- */
    if (X583A && X583A.poem) {
      var ov = document.createElement('div');
      ov.id = 'x583Poem';
      var pi = document.createElement('div');
      pi.className = 'x583-call x583-poemimg';
      pi.appendChild(img('poem'));
      ov.appendChild(pi);
      var hint = document.createElement('div');
      hint.className = 'x583-poemhint';
      hint.textContent = '心之所向 · 即将启程';
      ov.appendChild(hint);
      document.body.appendChild(ov);
      var origFlow = window.startFlow;
      window.__x583PoemShown = false;
      window.startFlow = function () {
        if (window.__x583PoemShown) { if (typeof origFlow === 'function') return origFlow(); return; }
        window.__x583PoemShown = true;
        ov.classList.add('show');
        ov.addEventListener('click', function () { ov.classList.remove('show'); if (typeof origFlow === 'function') origFlow(); });
        T.setTimeout(function () { ov.classList.remove('show'); if (typeof origFlow === 'function') origFlow(); }, 3200);
      };
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();


