/* ===== X580/581 fragment: patch583_petals.js ===== */
/* patch583_petals.js
   季节飘花 / 飘星：白天(亮主题)花瓣与玫瑰飘落；黑夜(暗主题)星星落到地下。
   稀疏不乱、可在设置里关闭；进入游戏后启用，片头/首页不遮挡。 */
(function () {
  if (window.__X583_PETALS__) return; window.__X583_PETALS__ = true;
  var X = (window.X583 = window.X583 || {});
  var T = (window.X581 && X581.timer) ? X581.timer : { setInterval: function (f, t) { return setInterval(f, t); }, setTimeout: function (f, t) { return setTimeout(f, t); } };

  var PETALS = ['🌸', '🌺', '🌹', '🌷', '🍃'];
  var STARS = ['✨', '⭐', '🌟', '·'];
  var layer = null, enabled = true, mode = null, spawnTimer = null;

  function isDarkTheme() { return document.body.classList.contains('x583-dark'); }
  function inGame() {
    var g = document.getElementById('game');
    return !!(g && getComputedStyle(g).display !== 'none');
  }
  function nightHour() {
    try {
      var g = window.G;
      if (g && g.time) {
        var m = String(g.time).match(/(\d{1,2}):(\d{2})/);
        if (m) { var h = +m[1]; return (h >= 19 || h < 6); }
      }
    } catch (e) {}
    return null;
  }
  function decideMode() {
    var nh = nightHour();
    /* 游戏内以时间为准：夜晚飘星，白天飘花；非游戏内以主题为准 */
    if (nh === true) return 'star';
    if (nh === false) return 'petal';
    return isDarkTheme() ? 'star' : 'petal';
  }
  function ensureLayer() {
    if (layer) return layer;
    layer = document.createElement('div');
    layer.id = 'x583Petals';
    layer.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:600;overflow:hidden';
    document.body.appendChild(layer);
    return layer;
  }
  function spawn() {
    if (!enabled || !inGame()) { if (layer) layer.innerHTML = ''; return; }
    var m = decideMode();
    var L = ensureLayer();
    var isStar = m === 'star';
    var el = document.createElement('span');
    el.className = 'x583-petal';
    var chars = isStar ? STARS : PETALS;
    el.textContent = chars[Math.floor(Math.random() * chars.length)];
    var size = isStar ? (10 + Math.random() * 10) : (14 + Math.random() * 12);
    var left = Math.random() * 100;
    var dur = 9 + Math.random() * 8;
    var drift = (Math.random() * 120 - 60) + 'px';
    var rot = (Math.random() * 540 - 120) + 'deg';
    el.style.left = left + 'vw';
    el.style.fontSize = size + 'px';
    el.style.animationDuration = dur + 's';
    el.style.setProperty('--drift', drift);
    el.style.setProperty('--rot', rot);
    if (isStar) {
      el.style.filter = 'drop-shadow(0 0 6px rgba(190,220,255,.9))';
      el.style.opacity = '0.85';
    } else {
      el.style.opacity = '0.9';
    }
    L.appendChild(el);
    T.setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, (dur + 1) * 1000);
    /* 控制密度：屏幕上最多 18 个 */
    while (L.childNodes.length > 18) L.removeChild(L.firstChild);
  }
  function loop() {
    if (!enabled) return;
    var m = decideMode();
    if (mode !== m) { mode = m; if (layer) layer.innerHTML = ''; }
    if (inGame()) spawn();
  }
  X.petals = {
    toggle: function () {
      enabled = !enabled;
      try { localStorage.setItem('x583_petals', enabled ? '1' : '0'); } catch (e) {}
      if (!enabled && layer) layer.innerHTML = '';
      return enabled;
    },
    set: function (v) { enabled = !!v; if (!enabled && layer) layer.innerHTML = ''; }
  };
  function start() {
    try { if (localStorage.getItem('x583_petals') === '0') enabled = false; } catch (e) {}
    /* 稀疏：每 1.4 秒最多生成一片 */
    T.setInterval(loop, 1400);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();


/* ===== X580/581 fragment: patch583_char.js ===== */
/* patch583_char.js
   建角两套版本切换：默认新版（#x570Char），可一键切到经典版（#charPanel，选项更全）；
   经典版也可一键切回新版。并全局兜底修掉"reading 'target'"（裸 event.target）。 */
(function () {
  if (window.__X583_CHAR__) return; window.__X583_CHAR__ = true;
  var X = (window.X583 = window.X583 || {});
  var T = (window.X581 && X581.timer) ? X581.timer : { setInterval: function (f, t) { return setInterval(f, t); }, setTimeout: function (f, t) { return setTimeout(f, t); } };

  function visible(el) {
    if (!el) return false;
    var cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') return false;
    /* fixed 定位元素 offsetParent 常为 null，改用包围盒判定 */
    var r = el.getBoundingClientRect();
    return r.width > 0 && r.height > 0;
  }
  function btnHtml(text) {
    return '<div id="x583CharSwitch" style="text-align:center;margin:10px 0">' +
      '<button class="gbtn" style="min-height:46px;padding:0 22px;width:100%;max-width:420px;border:1px dashed var(--line,#999);background:transparent">' + text + '</button></div>';
  }
  /* 隐藏新版面板 */
  function hideNew() {
    var xc = document.getElementById('x570Char');
    if (xc) { xc.classList.remove('show'); xc.style.display = 'none'; }
    document.querySelectorAll('.x570-full.show').forEach(function (f) {
      if (f.id === 'x570Char') { f.classList.remove('show'); f.style.display = 'none'; }
    });
  }
  function showClassic() {
    hideNew();
    try {
      if (typeof showCharCreate === 'function') { showCharCreate(); }
      var cp = document.getElementById('charPanel');
      if (cp) { cp.style.display = 'block'; cp.scrollTop = 0; }
    } catch (e) {}
  }
  function showNew() {
    var cp = document.getElementById('charPanel');
    if (cp) cp.style.display = 'none';
    var xc = document.getElementById('x570Char');
    if (xc) { xc.style.display = ''; xc.classList.add('show'); }
    try {
      if (window.X570 && X570.Char && X570.Char.open) { X570.Char.open(); return; }
    } catch (e) {}
  }

  function injectIntoNew() {
    var xc = document.getElementById('x570Char');
    if (!visible(xc)) return;
    if (document.getElementById('x583CharSwitch')) return;
    var body = xc.querySelector('.x570-full-body') || xc;
    var wrap = document.createElement('div');
    wrap.innerHTML = btnHtml('⇄ 切换到经典版建角（彩蛋角色 / 身高体重体脂 / 更多选项）');
    var node = wrap.firstElementChild;
    body.insertBefore(node, body.firstChild);
    node.querySelector('button').onclick = function () { showClassic(); };
  }
  function injectIntoClassic() {
    var cp = document.getElementById('charPanel');
    if (!visible(cp)) return;
    if (cp.querySelector('#x583CharSwitch')) return;
    var wrap = document.createElement('div');
    wrap.innerHTML = btnHtml('⇄ 切换到新版建角（推荐，手机竖屏更顺手）');
    var node = wrap.firstElementChild;
    /* 插到标题后面 */
    var h1 = cp.querySelector('h1') || cp.firstChild;
    if (h1 && h1.parentNode) h1.parentNode.insertBefore(node, h1.nextSibling);
    else cp.insertBefore(node, cp.firstChild);
    node.querySelector('button').onclick = function () { showNew(); };
  }
  function tick() {
    try { injectIntoNew(); } catch (e) {}
    try { injectIntoClassic(); } catch (e) {}
  }

  /* 全局兜底：裸 event.target 报错（旧穿搭/建角里 onClick 依赖全局 event） */
  function guardEvent() {
    try {
      if (window.__xzDressTab && !window.__xzDressTab.__guarded) {
        var old = window.__xzDressTab;
        window.__xzDressTab = function (cat, ev) {
          var e = ev || (window.event);
          document.querySelectorAll('.xz-dress-tab').forEach(function (t) { t.classList.remove('active'); });
          var t = e && e.target;
          if (t) t.classList.add('active');
          if (window.DRESS_CATS && DRESS_CATS[cat]) {
            var items = DRESS_CATS[cat].items;
            var saved = {};
            try { saved = JSON.parse(localStorage.getItem('xz_dress_set') || '{}'); } catch (er) {}
            var html = items.map(function (it) {
              var equipped = saved[cat] === it;
              return '<div class="xz-dress-item' + (equipped ? ' equipped' : '') + '" onclick="window.__xzDressEquip(\'' + cat + '\',\'' + it + '\')"><span class="d-emoji">' + DRESS_CATS[cat].emoji + '</span>' + it + '</div>';
            }).join('');
            var box = document.getElementById('xzDressItems'); if (box) box.innerHTML = html;
          }
        };
        window.__xzDressTab.__guarded = true;
      }
    } catch (e) {}
  }

  function boot() {
    T.setInterval(tick, 800);
    T.setInterval(guardEvent, 1200);
    T.setTimeout(tick, 600);
  }
  X.CharSwitch = { showNew: showNew, showClassic: showClassic };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();


